#!/usr/bin/env python3
"""Persona Matrix Generator — Step 6.8.5 Enhancement

Generates different founder-persona per chain link with info asymmetry tracking.

Usage:
  python persona-matrix-generator.py --chain '["Founder", "CTO", "VP", "Director"]'
  python persona-matrix-generator.py --chain '["Founder", "LP Partner"]' --wound-map /tmp/wound-map.json --profile-file /tmp/profile.json
"""

import argparse
import json
import sys
from pathlib import Path

if sys.platform == "win32":
    sys.stdout.reconfigure(encoding="utf-8")

POSITION_ARCHETYPES = {
    "introducer": {
        "identity": "Helpful peer who solves real problems",
        "energy": "builder",
        "lead_with": ["technical competence", "problem-solving speed"],
        "never_mention": ["target relationship goals", "investment ambitions", "strategic intent"],
    },
    "lieutenant": {
        "identity": "Respectful student with unique data access",
        "energy": "scholar",
        "lead_with": ["specialized knowledge", "market intelligence"],
        "never_mention": ["target relationship goals", "being sent by someone"],
    },
    "target": {
        "identity": "Peer builder on parallel journey — not applicant",
        "energy": "equal",
        "lead_with": ["shared challenges", "mutual value creation"],
        "never_mention": ["needing anything", "being introduced for a purpose"],
    },
    "lp": {
        "identity": "Vietnam/SEA market specialist with ground-level access",
        "energy": "expert",
        "lead_with": ["exclusive market data", "on-ground relationships"],
        "never_mention": ["fund relationship goals", "being connected to fund team"],
    },
}

LP_KEYWORDS = {"lp", "investor", "limited partner", "fund", "vc", "venture"}


def classify_chain_position(role: str, chain: list, index: int) -> str:
    """Determine position type based on role keywords and chain index."""
    role_lower = role.lower()
    if any(kw in role_lower for kw in LP_KEYWORDS):
        return "lp"
    # index 0 = Founder (skip), index 1 = first link after founder
    non_founder_index = index - 1  # 0-based among non-founder links
    non_founder_count = len(chain) - 1
    if non_founder_index == 0:
        return "introducer"
    if non_founder_index == non_founder_count - 1:
        return "target"
    return "lieutenant"


def _cultural_mode(founder_profile: dict, wound_entry: dict) -> str:
    """Infer cultural mode from seniority signals in wound map entry."""
    seniority = wound_entry.get("seniority", "").lower()
    if any(s in seniority for s in ("senior", "vp", "director", "cto", "ceo", "partner", "managing")):
        return "de_tu"
    if any(s in seniority for s in ("analyst", "associate", "junior", "coordinator")):
        return "expert"
    return "peer"


def _match_lead_with(founder_profile: dict, wound_entry: dict, archetype: dict) -> list:
    """Merge archetype defaults with founder-skill matches against wound needs."""
    base = list(archetype["lead_with"])
    skills = founder_profile.get("skills", [])
    if isinstance(skills, str):
        skills = [s.strip() for s in skills.split(",")]
    needs = wound_entry.get("needs_not_wants", wound_entry.get("pain_points", []))
    if isinstance(needs, str):
        needs = [needs]
    for skill in skills[:3]:
        for need in needs:
            if any(word in need.lower() for word in skill.lower().split()):
                if skill not in base:
                    base.insert(0, skill)
                    break
    return base[:4]


def generate_persona(
    founder_profile: dict,
    target_role: str,
    wound_map_entry: dict,
    position: str,
) -> dict:
    """Build persona dict for a single chain link."""
    archetype = POSITION_ARCHETYPES[position]
    return {
        "target_role": target_role,
        "chain_position": position,
        "persona": {
            "identity": archetype["identity"],
            "energy": archetype["energy"],
            "lead_with": _match_lead_with(founder_profile, wound_map_entry, archetype),
            "never_mention": list(archetype["never_mention"]),
            "cultural_mode": _cultural_mode(founder_profile, wound_map_entry),
        },
    }


def map_info_state(
    founder_profile: dict,
    target_role: str,
    wound_map_entry: dict,
) -> dict:
    """Build info-asymmetry state for a single chain link."""
    public_assets = founder_profile.get("public_assets", ["name", "LinkedIn profile", "public posts"])
    if isinstance(public_assets, str):
        public_assets = [public_assets]

    known_about_them = wound_map_entry.get("known_signals", [])
    if not known_about_them:
        known_about_them = [
            w for w in [
                wound_map_entry.get("portfolio_struggles"),
                wound_map_entry.get("hiring_gaps"),
                wound_map_entry.get("fund_pressure"),
                wound_map_entry.get("pain_points"),
            ] if w
        ]

    asymmetry_note = wound_map_entry.get(
        "asymmetry_note",
        f"You know their operational gaps; they see only your public surface.",
    )

    return {
        "target_role": target_role,
        "they_know_about_you": list(public_assets),
        "you_know_about_them": known_about_them,
        "asymmetry_advantage": asymmetry_note,
        "reveal_sequence": [
            {"week": 1, "reveal": "technical competence", "why": "establish credibility, low risk"},
            {"week": 3, "reveal": "Vietnam market depth", "why": "create need, show unique value"},
            {"week": 6, "reveal": "LP/investor connections", "why": "escalate value suddenly, trigger discovery illusion"},
        ],
        "never_reveal": [
            "wound map knowledge",
            "chain design",
            "compound objectives",
            "strategic intent",
        ],
        "share_keep_ratio": {
            "share_80pct": ["market data", "introductions", "analysis", "problem-solving"],
            "keep_20pct": ["exclusive relationships", "critical intel", "unique access", "timing leverage"],
        },
    }


def check_persona_consistency(personas: list) -> dict:
    """Verify personas won't contradict each other if targets compare notes."""
    conflicts = []
    identities = [(p["target_role"], p["persona"]["identity"]) for p in personas]
    # Check: never_mention items don't appear as lead_with in same-chain personas
    all_never = set()
    for p in personas:
        all_never.update(p["persona"]["never_mention"])
    for p in personas:
        for item in p["persona"]["lead_with"]:
            for forbidden in all_never:
                if item.lower() == forbidden.lower():
                    conflicts.append(
                        f"{p['target_role']}: lead_with '{item}' conflicts with never_mention rule '{forbidden}'"
                    )
    # Check energy contradiction: no two personas claim opposite identities
    energies = [p["persona"]["energy"] for p in personas]
    if "equal" in energies and "de_tu" in [p["persona"]["cultural_mode"] for p in personas]:
        # Allowed: different modes for different targets
        pass
    return {"consistent": len(conflicts) == 0, "conflicts": conflicts}


def check_info_leaks(personas: list, info_states: list) -> dict:
    """Verify nothing in never_reveal surfaces in any persona's lead_with."""
    leaks = []
    all_never_reveal = set()
    for state in info_states:
        all_never_reveal.update(state.get("never_reveal", []))
    for p in personas:
        for item in p["persona"]["lead_with"]:
            for forbidden in all_never_reveal:
                if forbidden.lower() in item.lower():
                    leaks.append(
                        f"{p['target_role']}: lead_with '{item}' leaks never_reveal '{forbidden}'"
                    )
    return {"clean": len(leaks) == 0, "leaks": leaks}


def generate_matrix(chain: list, founder_profile: dict, wound_map: dict) -> dict:
    """Main function — generate persona matrix for the full chain."""
    personas = []
    info_states = []
    chain_labels = []

    for i, role in enumerate(chain):
        if i == 0:
            chain_labels.append(role)
            continue
        position = classify_chain_position(role, chain, i)
        wound_entry = wound_map.get(role, wound_map.get(role.lower(), {}))
        if not wound_entry and wound_map:
            # Fallback: use first wound map entry if role not found
            wound_entry = next(iter(wound_map.values()), {})

        persona = generate_persona(founder_profile, role, wound_entry, position)
        info_state = map_info_state(founder_profile, role, wound_entry)
        personas.append(persona)
        info_states.append(info_state)
        chain_labels.append(f"{role} ({position})")

    consistency = check_persona_consistency(personas)
    leaks = check_info_leaks(personas, info_states)

    return {
        "chain": chain_labels,
        "personas": personas,
        "info_states": info_states,
        "consistency_check": consistency,
        "leak_check": leaks,
        "compound_density_note": "Each persona interaction achieves ≥2 objectives",
    }


def main():
    parser = argparse.ArgumentParser(description="Persona Matrix Generator (Step 6.8.5 Enhancement)")
    parser.add_argument("--chain", required=True, help="JSON array of chain links e.g. '[\"Founder\", \"CTO\"]'")
    parser.add_argument("--wound-map", default=None, help="Path to wound map JSON from wound-extractor.py")
    parser.add_argument("--profile-file", default=None, help="Path to founder profile JSON")
    args = parser.parse_args()

    try:
        chain = json.loads(args.chain)
    except json.JSONDecodeError as e:
        print(json.dumps({"error": f"Invalid --chain JSON: {e}"}))
        sys.exit(1)

    if not isinstance(chain, list) or len(chain) < 2:
        print(json.dumps({"error": "--chain must be a JSON array with at least 2 elements (Founder + 1 link)"}))
        sys.exit(1)

    wound_map = {}
    if args.wound_map:
        wp = Path(args.wound_map)
        if wp.exists():
            with open(wp, "r", encoding="utf-8") as f:
                wound_map = json.load(f)

    founder_profile = {}
    if args.profile_file:
        pp = Path(args.profile_file)
        if pp.exists():
            with open(pp, "r", encoding="utf-8") as f:
                founder_profile = json.load(f)

    matrix = generate_matrix(chain, founder_profile, wound_map)
    print(json.dumps(matrix, indent=2, ensure_ascii=False))


if __name__ == "__main__":
    main()
